import{_ as t,o,c as i,a2 as a}from"./chunks/framework.CRkTBNIT.js";const p=JSON.parse('{"title":"Step 12: Technical Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),r={name:"11-glossary.md"};function s(n,e,l,c,d,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="step-12-technical-glossary" tabindex="-1">Step 12: Technical Glossary <a class="header-anchor" href="#step-12-technical-glossary" aria-label="Permalink to &quot;Step 12: Technical Glossary&quot;">​</a></h1><p>Simple, precise definitions of technical terms used across OmniPost (<code>20-notification-delivery-platform</code>).</p><ul><li><strong>AsyncIO</strong>: Python&#39;s built-in asynchronous framework using an event loop to achieve cooperative multitasking without OS thread overhead.</li><li><strong>Circuit Breaker</strong>: A resilience design pattern that detects upstream provider failures and temporarily diverts traffic to prevent cascading system crashes.</li><li><strong>Dead-Letter Queue (DLQ)</strong>: A storage buffer that holds messages that have repeatedly failed delivery and exhausted all retry attempts, isolating them for manual inspection.</li><li><strong>Exponential Backoff</strong>: An algorithm that exponentially increases the wait time between retry attempts (e.g. 1s, 2s, 4s, 8s) to give recovering services time to stabilize.</li><li><strong>Full Jitter</strong>: A randomization technique added to exponential backoff that uniformly spreads retry delays between zero and the calculated ceiling to prevent thundering herd spikes.</li><li><strong>HMAC-SHA256</strong>: Hash-based Message Authentication Code combining a cryptographic hash function with a secret key to verify data integrity and authenticity.</li><li><strong>Idempotency Key</strong>: A unique client-supplied token that guarantees performing the same operation multiple times produces the exact same outcome without duplicate actions.</li><li><strong>Jinja2 SandboxedEnvironment</strong>: A restricted AST execution environment that disables access to Python internal methods and dangerous built-ins to block Server-Side Template Injection.</li><li><strong>Lease-Based Locking</strong>: A distributed concurrency pattern where a worker claims a job for a limited duration (<code>locked_until</code>); if the worker dies, the lease expires and another worker reclaims it.</li><li><strong>Monotonic State Machine</strong>: A finite state machine whose status transitions can only move forward along allowable paths, never regressing to previous states.</li><li><strong>Provider Capability Matrix</strong>: A registry defining the features, maximum payload sizes, channels, and costs supported by each third-party delivery vendor.</li><li><strong>Quiet Hours</strong>: Defined nighttime hours (e.g. 22:00 to 08:00) during which non-critical promotional notifications are suppressed to respect user privacy and telecom regulations.</li><li><strong>Role-Based Access Control (RBAC)</strong>: An authorization approach where permissions are assigned to roles (<code>ADMIN</code>, <code>OPERATOR</code>, <code>VIEWER</code>), and users are assigned to roles.</li><li><strong>Starvation Protection</strong>: An algorithm that promotes aged, low-priority tasks when high-priority tasks continuously monopolize worker processing capacity.</li><li><strong>Token Bucket Rate Limiter</strong>: An algorithm that maintains a bucket of tokens refilled at a constant rate; each request consumes a token, allowing controlled bursts while enforcing average throughput.</li></ul>',3)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
